function expand_block(expander,block){block.css('max-height','none');$(block).find('.performer-li').removeClass('hidden');$(block).removeClass('expandable');expander.hide();event.stopPropagation()}
function valid_email(value){return value.length<=80&&(/^[\w_.-]+@([\w-]+\.)+\w{2,}$/.test(value))}
function isMobile(){return/Mobi|Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent)}
function isIOS(){return/iP(ad|hone|od)/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1)}
function isAndroid(){return/Android/i.test(navigator.userAgent)}
function isSafari(){return/^((?!chrome|android).)*safari/i.test(navigator.userAgent)}
function pageFromEvent(e,page){let e_target=$(e.target);if(!e_target.hasClass('page-link')&&e_target.parent().hasClass('page-link')){e_target=e_target.parent()}
return e_target.data('page')||page}
function allowed_key(e){var allowed_code=[0,8,13,32,44,45,46,95];var cc=(e.charCode)?e.charCode:((e.keyCode)?e.keyCode:((e.which)?e.which:0));return(allowed_code.indexOf(cc)>-1||(cc>46&&cc<91)||(cc>95&&cc<112)||(cc>145))}
let tooltipHideTimer=null;$(document).on('touchstart','[data-tooltip]',function(){const el=this;$('[data-tooltip-visible]').not(el).removeAttr('data-tooltip-visible');el.setAttribute('data-tooltip-visible','');clearTimeout(tooltipHideTimer);tooltipHideTimer=setTimeout(function(){el.removeAttribute('data-tooltip-visible')},2000)});function performer_search_suggest_apply(e,min_search_text_length=1){var input=$(e.target);var search_text=input.val().trim().substring(0,SEARCH_MAX_LEN);var search_box_result_block=input.closest('.search-box').find('.search-box-result');search_box_result_block.html("");search_box_result_block.hide();if((search_text.length>=min_search_text_length)||(search_text.startsWith('#')&&search_text.length>1)){if(e.keyCode===13&&!input.is('[data-no-enter-redirect]')){if(search_text.startsWith('#')){window.location.href=backendLinks.tag+encodeURIComponent(search_text.substring(1))}
return}
let url=backendLinks.performers+"/search-suggest/"+encodeURIComponent(search_text);const performersOnly=input.data('performers-only');if(performersOnly)url+='?performers_only=1';const previousXhr=input.data('search-suggest-xhr');if(previousXhr)previousXhr.abort();const xhr=rFetch({url:url,type:"post",success:function(response){if(response.length>0){search_box_result_block.html(response);search_box_result_block.show();lazyLoadSearchThumbs(search_box_result_block[0])}},error:function(xhr){}});input.data('search-suggest-xhr',xhr)}
input.removeAttr('searching')}
function performer_search_suggest_keynav(event){if(event.key!=='ArrowDown'&&event.key!=='ArrowUp'&&event.key!=='ArrowLeft'&&event.key!=='ArrowRight'&&event.key!=='Enter')return;const $input=$(event.target);const $resultBlock=$input.closest('.search-box').find('.search-box-result');if(!$resultBlock.is(':visible'))return;const $items=$resultBlock.find('.performer-li > a.dropdown-item');if($items.length===0)return;const current=$items.index($items.filter('.active'));if(event.key==='Enter'){if(current<0)return;event.preventDefault();$input.data('skip-search',!0);$items.eq(current)[0].click();return}
const cols=performer_search_suggest_columns($items);if((event.key==='ArrowLeft'||event.key==='ArrowRight')&&cols<2)return;event.preventDefault();$resultBlock.addClass('keynav-active');let next;if(current<0){next=(event.key==='ArrowDown'||event.key==='ArrowRight')?0:$items.length-1}else if(event.key==='ArrowDown'){next=(current+cols)%$items.length}else if(event.key==='ArrowUp'){next=(current-cols+$items.length)%$items.length}else if(event.key==='ArrowRight'){next=(current+1)%$items.length}else{next=(current-1+$items.length)%$items.length}
performer_search_suggest_select($items,next)}
function performer_search_suggest_columns($items){if($items.length<2)return 1;const firstTop=Math.round($items[0].getBoundingClientRect().top);let cols=0;for(let i=0;i<$items.length;i++){if(Math.round($items[i].getBoundingClientRect().top)===firstTop)cols++;else break}
return Math.max(1,cols)}
function performer_search_suggest_select($items,index){$items.removeClass('active');const $selected=$items.eq(index);$selected.addClass('active');const el=$selected[0];if(el&&el.scrollIntoView)el.scrollIntoView({block:'nearest'})}
function bootstrap_dropdown_keynav(event){const key=event.key;if(key!=='ArrowDown'&&key!=='ArrowUp'&&key!=='ArrowLeft'&&key!=='ArrowRight'&&key!=='Escape'&&key!=='Enter')return;const $active=$(document.activeElement||document.body);if($active.is('textarea, [contenteditable="true"]'))return;if($active.hasClass('js-performer-search-suggest'))return;if($active.closest('.search-box-result').length)return;const isToggle=$active.is('[data-bs-toggle="dropdown"]');const $containingMenu=$active.closest('.dropdown-menu');const insideMenu=$containingMenu.length>0;if(isToggle&&!insideMenu){if(key==='ArrowLeft'||key==='ArrowRight'){bootstrap_dropdown_sibling_toggle_nav(event,$active,key)}else if(key==='ArrowDown'||key==='ArrowUp'){bootstrap_dropdown_open_and_focus(event,$active,key)}
return}
if(isToggle&&insideMenu&&(key==='ArrowRight'||key==='Enter')){bootstrap_dropdown_open_and_focus(event,$active,'ArrowDown');return}
let $menu;if(insideMenu){$menu=$containingMenu}else{$menu=$('.dropdown-menu.show').filter(':visible').first()}
if($menu.length===0)return;if(key==='ArrowLeft'){bootstrap_dropdown_submenu_back(event,$menu)}else if(key==='Escape'){bootstrap_dropdown_close(event,$menu)}else if(key==='ArrowDown'||key==='ArrowUp'){bootstrap_dropdown_item_nav(event,$active,$menu,key)}}
function bootstrap_dropdown_focus_item(el){if(!el)return;if(!el.hasAttribute('tabindex'))el.setAttribute('tabindex','-1');el.focus();if(el.scrollIntoView)el.scrollIntoView({block:'nearest'})}
function bootstrap_dropdown_open_and_focus(event,$toggle,key){let $menu=$toggle.nextAll('.dropdown-menu').first();if($menu.length===0)$menu=$toggle.parent().children('.dropdown-menu').first();if($menu.length===0)return;event.preventDefault();event.stopImmediatePropagation();$menu.addClass('keynav-active');if(!$menu.hasClass('show')&&window.bootstrap&&window.bootstrap.Dropdown){const instance=window.bootstrap.Dropdown.getOrCreateInstance($toggle[0]);instance.show()}
const $items=bootstrap_dropdown_navigables($menu);if($items.length===0)return;bootstrap_dropdown_focus_item(key==='ArrowDown'?$items.first()[0]:$items.last()[0])}
function bootstrap_dropdown_navigables($menu){const menuEl=$menu[0];const isBsMenu=menuEl.classList.contains('dropdown-menu');const belongsToMenu=(el)=>{if(isBsMenu)return $(el).closest('.dropdown-menu')[0]===menuEl;return menuEl.contains(el)};const $input=$menu.find('input[type="text"], input[type="search"], input:not([type])').filter(':visible:not(:disabled)').filter(function(){return belongsToMenu(this)}).first();const $items=$menu.find('.dropdown-item, .tag-li a[href], .item-li a[href], .performer-li a[href], li > a[href]').add($menu.children('button, a[href]')).filter(function(){const $el=$(this);if($el.is(':disabled, .disabled, .dropdown-item-head'))return!1;if(!$el.is(':visible'))return!1;if(!belongsToMenu(this))return!1;return!0});return $input.length>0?$input.add($items):$items}
function bootstrap_dropdown_submenu_back(event,$menu){const $toggle=$menu.parent().children('[data-bs-toggle="dropdown"]').first();if($toggle.length===0)return;if($toggle.closest('.dropdown-menu').length===0)return;event.preventDefault();event.stopImmediatePropagation();if(window.bootstrap&&window.bootstrap.Dropdown){const instance=window.bootstrap.Dropdown.getOrCreateInstance($toggle[0]);instance.hide()}
$toggle[0].focus()}
function bootstrap_dropdown_item_nav(event,$active,$openMenu,key){const $items=bootstrap_dropdown_navigables($openMenu);if($items.length===0)return;event.preventDefault();event.stopImmediatePropagation();$openMenu.addClass('keynav-active');let currentIdx=-1;$items.each(function(i){if(this===$active[0]){currentIdx=i;return!1}});let nextIdx;if(currentIdx===-1){nextIdx=key==='ArrowDown'?0:$items.length-1}else{nextIdx=key==='ArrowDown'?(currentIdx+1)%$items.length:(currentIdx-1+$items.length)%$items.length}
bootstrap_dropdown_focus_item($items.eq(nextIdx)[0])}
function bootstrap_dropdown_sibling_toggle_nav(event,$toggle,key){const $dropdown=$toggle.closest('.dropdown, .btn-group');let $toggles=$dropdown.parent().find('[data-bs-toggle="dropdown"]').filter(':visible:not(:disabled)');if($toggles.length<2)return;const currentIdx=$toggles.index($toggle);if(currentIdx===-1)return;let nextIdx=key==='ArrowRight'?currentIdx+1:currentIdx-1;if(nextIdx<0||nextIdx>=$toggles.length)return;event.preventDefault();event.stopImmediatePropagation();$toggles.eq(nextIdx)[0].focus()}
function bootstrap_dropdown_close(event,$openMenu){const $toggle=$openMenu.closest('.dropdown, .btn-group').find('[data-bs-toggle="dropdown"]').first();if($toggle.length===0)return;event.preventDefault();event.stopImmediatePropagation();if(window.bootstrap&&window.bootstrap.Dropdown){const instance=window.bootstrap.Dropdown.getOrCreateInstance($toggle[0]);instance.hide()}
$toggle[0].focus()}
function lazyLoadSearchThumbs(rootEl){const thumbs=rootEl.querySelectorAll('.performer-li-thumb[data-bg]');if(thumbs.length===0)return;const scrollContainer=rootEl.querySelector('.performer-results-scroll')||rootEl;const observer=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(!entry.isIntersecting)return;const el=entry.target;const url=el.dataset.bg;observer.unobserve(el);if(!url)return;const preload=new Image();preload.onload=()=>{el.style.backgroundImage="url('"+url+"')";el.classList.remove('shimmer-background');el.removeAttribute('data-bg')};preload.onerror=()=>{el.classList.remove('shimmer-background')};preload.src=url})},{root:scrollContainer,rootMargin:'100px'});thumbs.forEach(t=>observer.observe(t))}
function performers_search(e,function_name){if(!allowed_key(e)||e.metaKey||e.ctrlKey){return}
if($(e.target).data('skip-search')){$(e.target).removeData('skip-search');return}
let input=$(e.target);if(!input.attr('searching')){input.attr('searching',!0);setTimeout(eval(function_name),300,e)}}
function tags_search(e,function_name){if(!allowed_key(e)){return}
let input=$(e.target);input.removeAttr('searching');eval(function_name)(e)}
function redirect_countdown(n,url){if(0===n.length){return}
let t=n.text();if(t<=1){window.location=url}else{n.text(--t);setTimeout(function(){redirect_countdown(n,url)},1000)}}
function countdown(n){if(0===n.length){return}
let remainingTime=n.data('timeout');let span=n.find('span');remainingTime--;if(remainingTime<=1){span.text('');n.attr('class','btn btn-secondary btn-base')}else{n.data('timeout',remainingTime);let minutes=(remainingTime/60)|0;let seconds=(remainingTime%60)|0;minutes=minutes<10?"0"+minutes:minutes;seconds=seconds<10?"0"+seconds:seconds;span.text(minutes+":"+seconds);setTimeout(function(){countdown(n)},1000)}}
document.addEventListener("click",function(event){if(window.innerWidth<1024){const withinDropdown=event.target.closest(".dropdowns__dropdown");if(!withinDropdown){document.querySelectorAll(".dropdowns__dropdown-content-padding").forEach(function(content){content.style.opacity="0";content.style.pointerEvents="none"})}}})